from collections import deque


class ConnectGame:
    def __init__(self, board):
        # Each row is indented one space per row; strip the indent and
        # split on spaces to get the cells.
        self.board = [line.strip().split() for line in board.splitlines()]
        self.size = len(self.board)

    def _neighbors(self, row, col):
        for delta_row, delta_col in (
            (-1, -1), (-1, 0),
            (0, -1), (0, 1),
            (1, -1), (1, 0),
        ):
            r, c = row + delta_row, col + delta_col
            if 0 <= r < self.size and 0 <= c < self.size:
                yield r, c

    def _wins(self, player, start_edges):
        """Flood-fill from cells on start_edges; True if the opposite
        edge is reached."""
        visited = set()
        queue = deque()
        for row, col in start_edges:
            if self.board[row][col] == player:
                queue.append((row, col))
                visited.add((row, col))
        while queue:
            row, col = queue.popleft()
            if (row, col) in self._opposite_edge(start_edges):
                return True
            for r, c in self._neighbors(row, col):
                if (r, c) not in visited and self.board[r][c] == player:
                    visited.add((r, c))
                    queue.append((r, c))
        return False

    @staticmethod
    def _opposite_edge(edges):
        return edges

    def get_winner(self):
        # X connects the left edge to the right edge.
        left_edge = {(row, 0) for row in range(self.size)}
        right_edge = {(row, self.size - 1) for row in range(self.size)}
        if self._connects("X", left_edge, right_edge):
            return "X"
        # O connects the top edge to the bottom edge.
        top_edge = {(0, col) for col in range(self.size)}
        bottom_edge = {(self.size - 1, col) for col in range(self.size)}
        if self._connects("O", top_edge, bottom_edge):
            return "O"
        return ""

    def _connects(self, player, start_edges, goal_edges):
        visited = set()
        queue = deque()
        for cell in start_edges:
            if self.board[cell[0]][cell[1]] == player:
                queue.append(cell)
                visited.add(cell)
        while queue:
            row, col = queue.popleft()
            if (row, col) in goal_edges:
                return True
