from collections import deque


class ConnectGame:
    def __init__(self, board):
        # Each row is a space-separated sequence of cells; the leading
        # indentation is cosmetic, so strip it before splitting.
        self.board = [line.strip().split() for line in board.splitlines()]
        self.rows = len(self.board)
        self.cols = max(len(row) for row in self.board)

    def _cell(self, row, col):
        if 0 <= row < self.rows and 0 <= col < len(self.board[row]):
            return self.board[row][col]
        return None

    def _neighbors(self, row, col):
        # The board is a skewed parallelogram: each row is shifted half a
        # cell to the right, so a cell's six neighbours are:
        for r, c in (
            (row - 1, col), (row - 1, col + 1),
            (row, col - 1), (row, col + 1),
            (row + 1, col - 1), (row + 1, col),
        ):
            if self._cell(r, c) is not None:
                yield r, c

    def _connects(self, player, start_cells, goal_cells):
        """Flood-fill from the player's cells on start_cells and report
        whether any of them reaches goal_cells."""
        visited = set()
        queue = deque()
        for cell in start_cells:
            if self._cell(*cell) == player:
                queue.append(cell)
                visited.add(cell)
        while queue:
            cell = queue.popleft()
            if cell in goal_cells:
                return True
            for neighbor in self._neighbors(*cell):
                if neighbor not in visited and self._cell(*neighbor) == player:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    def get_winner(self):
        # Player X connects the left side to the right side.
        if self._connects(
            "X",
            {(row, 0) for row in range(self.rows)},
            {(row, self.cols - 1) for row in range(self.rows)},
        ):
            return "X"
        # Player O connects the top side to the bottom side.
        if self._connects(
            "O",
            {(0, col) for col in range(self.cols)},
            {(self.rows - 1, col) for col in range(self.cols)},
        ):
            return "O"
        return ""
